class EightPuzzle:
    # Replace Magic Number with Symbolic Constant
    BOARD_SIZE = 3
    GOAL_STATE = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]
    BLANK_VALUE = 0

    def __init__(self, initial_state):
        self.initial_state = initial_state
        # Replace Magic Number with Symbolic Constant / Replace Data Value with Object
        self.goal_state = self.GOAL_STATE

    def find_blank(self, state):
        # Replace Magic Number with Symbolic Constant
        for i in range(self.BOARD_SIZE):
            for j in range(self.BOARD_SIZE):
                if state[i][j] == self.BLANK_VALUE:
                    return i, j

    def _create_clone(self, state):
        return [row[:] for row in state]

    def _swap_up(self, state, i, j):
        state[i][j], state[i - 1][j] = state[i - 1][j], state[i][j]

    def _swap_down(self, state, i, j):
        state[i][j], state[i + 1][j] = state[i + 1][j], state[i][j]

    def _swap_left(self, state, i, j):
        state[i][j], state[i][j - 1] = state[i][j - 1], state[i][j]

    def _swap_right(self, state, i, j):
        state[i][j], state[i][j + 1] = state[i][j + 1], state[i][j]

    def move(self, state, direction):
        i, j = self.find_blank(state)
        new_state = self._create_clone(state)

        # Replace Nested Conditional with Guard Clauses / Decompose Conditional
        if direction == 'up':
            self._swap_up(new_state, i, j)
        elif direction == 'down':
            self._swap_down(new_state, i, j)
        elif direction == 'left':
            self._swap_left(new_state, i, j)
        elif direction == 'right':
            self._swap_right(new_state, i, j)

        return new_state

    def get_possible_moves(self, state):
        # Introduce Null Object / Encapsulate Collection / Introduce Explaining Variable
        moves = []
        i, j = self.find_blank(state)

        # Decompose Conditional / Extract Method
        if i > 0:
            moves.append('up')
        # Decompose Conditional / Extract Method
        if i < self.BOARD_SIZE - 1:
            moves.append('down')
        # Decompose Conditional / Extract Method
        if j > 0:
            moves.append('left')
        # Decompose Conditional / Extract Method
        if j < self.BOARD_SIZE - 1:
            moves.append('right')

        return moves

    def _is_goal_reached(self, state):
        return state == self.goal_state

    def _is_in_closed_list(self, state, closed_list):
        return state in closed_list

    def solve(self):
        # Encapsulate Collection / Separate Query from Modifier / Introduce Explaining Variable
        open_list = [(self.initial_state, [])]
        closed_list = []

        while open_list:
            # Extract Method / Introduce Explaining Variable
            current_state, path = open_list.pop(0)
            closed_list.append(current_state)

            # Replace Nested Conditional with Guard Clauses / Extract Method
            if self._is_goal_reached(current_state):
                return path

            # Replace Loop with Pipeline / Preserve Whole Object / Extract Method
            for move in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move)

                # Consolidate Duplicate Conditional Fragments / Remove Control Flag
                if not self._is_in_closed_list(new_state, closed_list):
                    open_list.append((new_state, path + [move]))

        return None
